-- Italy deep-dive content translations (ES/DE/FR)

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Compensación centralizada (SDI) — desde 2014', 'Esta página de análisis refleja la orientación técnica disponible públicamente a partir de julio de 2026 y se proporciona con fines informativos generales, no como asesoramiento legal o fiscal. Las versiones del esquema FatturaPA, los códigos de rechazo y los cálculos de sanciones siguen evolucionando — confirme los requisitos actuales directamente en el portal de la Agenzia delle Entrate antes de construir una integración.', 'Italia tiene el historial continuo más largo de cualquier régimen de facturación electrónica en la UE — la novedad de hoy es el mantenimiento del esquema, no un nuevo mandato.', 'FatturaPA es anterior a EN 16931 en su totalidad — es el esquema propio de Italia, no una implementación nacional de la norma europea.', 'El SDI es una verdadera cámara de compensación: una factura enviada directamente a un comprador, sin pasar por el SDI, simplemente no tiene validez legal en Italia.', 'Dado que el sistema de Italia lleva más de una década en funcionamiento, la mayor parte del trabajo de "registro" consiste en elegir el canal adecuado y acertar con el detalle técnico.', 'Italia separa las infracciones sustantivas del IVA de las meramente formales — ambas conllevan consecuencias muy distintas.' FROM countries WHERE name_en = 'Italy';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Zentralisiertes Clearing (SDI) — seit 2014', 'Diese Detailseite spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient allgemeinen Informationszwecken, nicht der Rechts- oder Steuerberatung. FatturaPA-Schemaversionen, Ablehnungscodes und Bußgeldberechnungen entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt im Portal der Agenzia delle Entrate, bevor Sie eine Integration aufbauen.', 'Italien hat die längste durchgehende Erfolgsbilanz jedes E-Invoicing-Regimes in der EU — die interessante Neuigkeit heute ist Schema-Pflege, kein neues Mandat.', 'FatturaPA geht EN 16931 vollständig voraus — es ist Italiens eigenes Schema, keine nationale Umsetzung der europäischen Norm.', 'Der SDI ist eine echte Clearingstelle: Eine direkt an einen Käufer gesendete Rechnung, die den SDI umgeht, hat in Italien schlicht keine Rechtsgültigkeit.', 'Da Italiens System seit über einem Jahrzehnt läuft, geht es bei der "Registrierung" größtenteils darum, den richtigen Kanal zu wählen und die technischen Details richtig zu machen.', 'Italien unterscheidet zwischen materiellen Mehrwertsteuerverstößen und rein formalen Verstößen — beide ziehen sehr unterschiedliche Konsequenzen nach sich.' FROM countries WHERE name_en = 'Italy';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Contrôle centralisé (SDI) — depuis 2014', 'Cette page d''analyse reflète les orientations techniques publiquement disponibles en date de juillet 2026 et est fournie à titre informatif général, non comme un avis juridique ou fiscal. Les versions du schéma FatturaPA, les codes de rejet et les calculs de sanctions continuent d''évoluer — confirmez les exigences actuelles directement sur le portail de l''Agenzia delle Entrate avant de construire une intégration.', 'L''Italie possède le plus long historique continu de tout régime de facturation électronique dans l''UE — l''actualité aujourd''hui, c''est la maintenance du schéma, pas un nouveau mandat.', 'FatturaPA est entièrement antérieur à EN 16931 — c''est le schéma propre à l''Italie, pas une mise en œuvre nationale de la norme européenne.', 'Le SDI est une véritable chambre de compensation : une facture envoyée directement à un acheteur, en contournant le SDI, n''a tout simplement aucune validité juridique en Italie.', 'Le système italien étant en place depuis plus d''une décennie, l''essentiel du travail « d''inscription » consiste surtout à choisir le bon canal et à bien maîtriser les détails techniques.', 'L''Italie distingue les infractions substantielles à la TVA des infractions purement formelles — les deux entraînent des conséquences très différentes.' FROM countries WHERE name_en = 'Italy';

