INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Esquema', '[["Formato", "FatturaPA XML — esquema propio de Italia"], ["Relación con EN 16931", "Anterior a la norma; no es una implementación CIUS"], ["Versión actual", "1.9.1 (obligatoria desde el 15 de mayo de 2026)"], ["Número de campos", "Más de 100 campos de datos obligatorios y opcionales"]]', 'No asuma que las herramientas EN 16931 creadas para Francia, Alemania o Polonia se adaptarán sin problemas a FatturaPA — el esquema tiene su propio linaje y sus propias reglas.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Estructura del documento', '[["Elemento raíz", "<FatturaElettronica>"], ["Bloque de cabecera", "FatturaElettronicaHeader (enrutamiento + partes)"], ["Campos de las partes", "CedentePrestatore (vendedor), CessionarioCommittente (comprador)"], ["Identificadores clave", "Codice Fiscale, Partita IVA"]]', 'La causa de rechazo más común en todas las fuentes sobre FatturaPA es siempre la misma: un Codice Fiscale o Partita IVA inválido en alguna de las partes. Valide esto antes que nada.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Firma digital', '[["Formato requerido", "XAdES o CAdES (.p7m)"], ["Se aplica a", "Cada factura, sin excepción"], ["Nomenclatura de archivo", "IT + número de IVA + _ + número progresivo"]]', 'A diferencia del KSeF de Polonia o del modelo de fiscalización de Croacia, Italia exige que el propio XML de la factura esté firmado digitalmente — esto ocurre a nivel del documento, no solo en la capa de transporte.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Archivado', '[["Período de conservación", "10 años — \"conservazione sostitutiva\""], ["Se aplica a", "Emisor y receptor"]]', 'La "conservazione sostitutiva" (conservación digital) es un régimen legal distinto del simple almacenamiento de archivos — tiene sus propios requisitos de integridad y accesibilidad según la legislación italiana.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Schema', '[["Format", "FatturaPA-XML — Italiens eigenes Schema"], ["Verhältnis zu EN 16931", "Geht dieser voraus; keine CIUS-Umsetzung"], ["Aktuelle Version", "1.9.1 (verpflichtend ab 15. Mai 2026)"], ["Feldanzahl", "Über 100 Pflicht- und optionale Datenfelder"]]', 'Gehen Sie nicht davon aus, dass EN-16931-Tools, die für Frankreich, Deutschland oder Polen entwickelt wurden, sauber auf FatturaPA übertragbar sind — das Schema hat seine eigene Historie und eigene Regeln.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Dokumentstruktur', '[["Wurzelelement", "<FatturaElettronica>"], ["Kopfblock", "FatturaElettronicaHeader (Routing + Parteien)"], ["Parteifelder", "CedentePrestatore (Verkäufer), CessionarioCommittente (Käufer)"], ["Zentrale Kennungen", "Codice Fiscale, Partita IVA"]]', 'Die häufigste Ablehnungsursache in allen Quellen zu FatturaPA ist stets dieselbe: eine ungültige Codice Fiscale oder Partita IVA bei einer der Parteien. Validieren Sie dies zuerst.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Digitale Signatur', '[["Erforderliches Format", "XAdES oder CAdES (.p7m)"], ["Gilt für", "Jede Rechnung, ohne Ausnahme"], ["Dateibenennung", "IT + USt-Nummer + _ + fortlaufende Nummer"]]', 'Anders als bei Polens KSeF oder Kroatiens Fiskalisierungsmodell verlangt Italien, dass die Rechnungs-XML selbst digital signiert wird — dies erfolgt auf Dokumentebene, nicht nur auf der Übertragungsebene.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Archivierung', '[["Aufbewahrungsfrist", "10 Jahre — \"conservazione sostitutiva\""], ["Gilt für", "Aussteller und Empfänger"]]', '"Conservazione sostitutiva" (digitale Aufbewahrung) ist ein eigenständiges Rechtsregime, das sich von einfacher Dateispeicherung unterscheidet — es hat eigene Integritäts- und Zugänglichkeitsanforderungen nach italienischem Recht.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Schéma', '[["Format", "XML FatturaPA — schéma propre à l''Italie"], ["Relation avec EN 16931", "Antérieur à la norme ; ce n''est pas une mise en œuvre CIUS"], ["Version actuelle", "1.9.1 (obligatoire à partir du 15 mai 2026)"], ["Nombre de champs", "Plus de 100 champs de données obligatoires et facultatifs"]]', 'Ne présumez pas que les outils EN 16931 conçus pour la France, l''Allemagne ou la Pologne se transposeront proprement sur FatturaPA — ce schéma a sa propre filiation et ses propres règles.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Structure du document', '[["Élément racine", "<FatturaElettronica>"], ["Bloc d''en-tête", "FatturaElettronicaHeader (routage + parties)"], ["Champs des parties", "CedentePrestatore (vendeur), CessionarioCommittente (acheteur)"], ["Identifiants clés", "Codice Fiscale, Partita IVA"]]', 'La cause de rejet la plus courante dans toutes les sources sur FatturaPA est toujours la même : un Codice Fiscale ou une Partita IVA invalide chez l''une des parties. Validez cela en priorité.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Signature électronique', '[["Format requis", "XAdES ou CAdES (.p7m)"], ["S''applique à", "Chaque facture, sans exception"], ["Nommage du fichier", "IT + numéro de TVA + _ + numéro progressif"]]', 'Contrairement au KSeF polonais ou au modèle de fiscalisation croate, l''Italie exige que le XML de la facture lui-même soit signé électroniquement — cela se situe au niveau du document, pas seulement de la couche de transport.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Archivage', '[["Durée de conservation", "10 ans — « conservazione sostitutiva »"], ["S''applique à", "L''émetteur et le destinataire"]]', 'La « conservazione sostitutiva » (conservation numérique) est un régime juridique distinct du simple stockage de fichiers — elle comporte ses propres exigences d''intégrité et d''accessibilité en vertu du droit italien.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Identificadores de enrutamiento', '[["Principal", "Codice Destinatario (código de 7 caracteres)"], ["Alternativa", "Dirección PEC (correo certificado)"], ["Si no se conoce ninguno", "Código fijado en 0000000, se usa la PEC"], ["Si ambos están presentes", "El SDI usa el Codice Destinatario, ignora la PEC"]]', 'Las empresas no italianas suelen obtener un Codice Destinatario a través de un intermediario o del módulo de conectividad SDI de su ERP, en lugar de registrarse directamente con la Agenzia delle Entrate.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Canales de transmisión', '[["Opciones", "PEC, carga web, SFTP, servicios web SDICoop"], ["Recibo de éxito", "Ricevuta di Consegna (recibo de entrega)"], ["Recibo de fallo", "Notifica di Scarto (rechazo, con código de error)"]]', 'Configure su flujo para gestionar explícitamente ambos tipos de recibo — una Notifica di Scarto significa que la factura nunca se emitió legalmente, no que simplemente se retrasó.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Reporte transfronterizo', '[["TD17", "Servicios adquiridos en el extranjero"], ["TD18", "Bienes adquiridos en la UE"], ["TD19", "Bienes adquiridos fuera de la UE"], ["Plazo", "Dentro de 12 días"]]', 'Estos tipos de documento absorbieron el antiguo sistema independiente de reporte "Esterometro" — ahora está totalmente integrado en el SDI en lugar de ser una declaración separada.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Routing-Kennungen', '[["Primär", "Codice Destinatario (7-stelliger Code)"], ["Ausweichlösung", "PEC-Adresse (zertifizierte E-Mail)"], ["Falls keine bekannt", "Code auf 0000000 gesetzt, PEC wird stattdessen verwendet"], ["Falls beide vorhanden", "SDI verwendet Codice Destinatario, ignoriert PEC"]]', 'Nicht-italienische Unternehmen erhalten einen Codice Destinatario in der Regel über einen Intermediär oder das SDI-Konnektivitätsmodul ihres ERP-Systems, anstatt sich direkt bei der Agenzia delle Entrate zu registrieren.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Übertragungskanäle', '[["Optionen", "PEC, Web-Upload, SFTP, SDICoop-Webdienste"], ["Erfolgsquittung", "Ricevuta di Consegna (Zustellquittung)"], ["Fehlerquittung", "Notifica di Scarto (Ablehnung, mit Fehlercode)"]]', 'Bauen Sie Ihre Pipeline so, dass beide Quittungsarten explizit verarbeitet werden — eine Notifica di Scarto bedeutet, dass die Rechnung rechtlich nie ausgestellt wurde, nicht nur, dass sie sich verzögert hat.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Grenzüberschreitende Meldung', '[["TD17", "Im Ausland erworbene Dienstleistungen"], ["TD18", "Aus der EU erworbene Waren"], ["TD19", "Von außerhalb der EU erworbene Waren"], ["Frist", "Innerhalb von 12 Tagen"]]', 'Diese Belegarten haben das frühere eigenständige "Esterometro"-Meldesystem übernommen — es ist jetzt vollständig in den SDI integriert, statt eine separate Meldung zu sein.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Identifiants de routage', '[["Principal", "Codice Destinatario (code à 7 caractères)"], ["Solution de repli", "Adresse PEC (courriel certifié)"], ["Si aucun des deux n''est connu", "Code fixé à 0000000, la PEC est utilisée à la place"], ["Si les deux sont présents", "Le SDI utilise le Codice Destinatario, ignore la PEC"]]', 'Les entreprises non italiennes obtiennent généralement un Codice Destinatario via un intermédiaire ou le module de connectivité SDI de leur ERP, plutôt que de s''inscrire directement auprès de l''Agenzia delle Entrate.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Canaux de transmission', '[["Options", "PEC, téléversement web, SFTP, services web SDICoop"], ["Accusé de réussite", "Ricevuta di Consegna (accusé de livraison)"], ["Accusé d''échec", "Notifica di Scarto (rejet, avec code d''erreur)"]]', 'Concevez votre pipeline pour traiter explicitement les deux types d''accusé — une Notifica di Scarto signifie que la facture n''a jamais été légalement émise, pas simplement retardée.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Déclaration transfrontalière', '[["TD17", "Services achetés à l''étranger"], ["TD18", "Biens achetés dans l''UE"], ["TD19", "Biens achetés hors de l''UE"], ["Délai", "Dans les 12 jours"]]', 'Ces types de documents ont absorbé l''ancien système de déclaration autonome « Esterometro » — il est désormais entièrement intégré au SDI plutôt que de faire l''objet d''une déclaration distincte.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'es', 'El flujo de compensación', 'Cada factura pasa por la misma secuencia:', 'El ciclo completo suele completarse en segundos o minutos, aunque el SDI permite formalmente hasta 5 días de procesamiento.' FROM deep_dive_lifecycle_cards lc JOIN countries co ON co.id = lc.country_id WHERE co.name_en = 'Italy' AND lc.section = 'scope_transmission' AND lc.sort_order = 3;
