INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'El SDI valida' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Italy' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'es', 'Entregar o rechazar' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Italy' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'de', 'Der Clearing-Ablauf', 'Jede Rechnung durchläuft dieselbe Abfolge:', 'Der gesamte Zyklus dauert in der Regel Sekunden bis Minuten, obwohl der SDI formal bis zu 5 Tage Bearbeitungszeit einräumt.' FROM deep_dive_lifecycle_cards lc JOIN countries co ON co.id = lc.country_id WHERE co.name_en = 'Italy' AND lc.section = 'scope_transmission' AND lc.sort_order = 3;
