INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'An SDI übertragen' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Italy' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'SDI validiert' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Italy' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'de', 'Zustellen oder ablehnen' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Italy' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT lc.id, 'fr', 'Le circuit de contrôle', 'Chaque facture suit la même séquence :', 'Le cycle complet se termine généralement en quelques secondes à quelques minutes, bien que le SDI autorise formellement jusqu''à 5 jours de traitement.' FROM deep_dive_lifecycle_cards lc JOIN countries co ON co.id = lc.country_id WHERE co.name_en = 'Italy' AND lc.section = 'scope_transmission' AND lc.sort_order = 3;
