INSERT OR IGNORE INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) SELECT ls.id, 'fr', 'Transmettre au SDI' FROM deep_dive_lifecycle_statuses_v2 ls JOIN deep_dive_lifecycle_cards lcc ON lcc.id = ls.card_id JOIN countries co ON co.id = lcc.country_id WHERE co.name_en = 'Italy' AND lcc.section = 'scope_transmission' AND lcc.sort_order = 3 AND ls.sort_order = 1;
