INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Registre un Codice Destinatario, o planee usar PEC', 'Las empresas italianas pueden registrarse directamente con la Agenzia delle Entrate a través del portal Fatture e Corrispettivi. Las empresas no italianas suelen recurrir a un intermediario o al módulo SDI de su ERP.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Adapte sus datos a FatturaPA v1.9.1', 'Valide específicamente contra el esquema actual — el cambio del 15 de mayo de 2026 implica que cualquier cosa que aún apunte a una versión anterior será rechazada de plano.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Aplique una firma digital cualificada a cada factura', 'Use el formato XAdES o CAdES (.p7m) — este es un requisito a nivel de documento que se aplica antes de la transmisión, no algo que el SDI añada en su nombre.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija su canal de transmisión', 'Elija entre PEC, carga web, SFTP o servicios web SDICoop según su volumen e infraestructura existente — SDICoop es el más adecuado para integraciones automatizadas de mayor volumen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure el manejo de rechazos y el seguimiento de recibos', 'Establezca flujos de trabajo para detectar rápidamente los rechazos por Notifica di Scarto (compruebe primero la validez del Codice Fiscale/Partita IVA) y para confirmar la entrega mediante Ricevuta di Consegna de cada factura enviada.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Configure el archivado de conservazione sostitutiva a 10 años', 'Se trata de un régimen de conservación digital distinto según la legislación italiana — confirme que su solución de archivado cumple sus requisitos específicos de integridad y accesibilidad, no solo el almacenamiento general de archivos.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Implemente el reporte TD17–TD19 si comercia de forma transfronteriza', 'Incorpore el plazo de reporte de 12 días en su proceso para servicios del extranjero y bienes de origen UE/no UE.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Registrieren Sie einen Codice Destinatario oder planen Sie die Nutzung von PEC', 'Italienische Unternehmen können sich direkt über das Fatture e Corrispettivi-Portal bei der Agenzia delle Entrate registrieren. Nicht-italienische Unternehmen nutzen in der Regel stattdessen einen Intermediär oder das SDI-Modul ihres ERP-Systems.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Ordnen Sie Ihre Daten FatturaPA v1.9.1 zu', 'Validieren Sie speziell gegen das aktuelle Schema — die Umstellung am 15. Mai 2026 bedeutet, dass alles, was noch auf eine ältere Version abzielt, rundweg zurückgewiesen wird.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Versehen Sie jede Rechnung mit einer qualifizierten digitalen Signatur', 'Verwenden Sie das Format XAdES oder CAdES (.p7m) — dies ist eine Anforderung auf Dokumentebene, die vor der Übertragung gilt und nicht vom SDI in Ihrem Namen hinzugefügt wird.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie Ihren Übertragungskanal', 'Wählen Sie je nach Volumen und vorhandener Infrastruktur zwischen PEC, Web-Upload, SFTP oder SDICoop-Webdiensten — SDICoop eignet sich am besten für automatisierte Integrationen mit hohem Volumen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bauen Sie Ablehnungsbehandlung und Quittungsverfolgung auf', 'Richten Sie Arbeitsabläufe ein, um Notifica-di-Scarto-Ablehnungen schnell zu erkennen (prüfen Sie zuerst die Gültigkeit von Codice Fiscale/Partita IVA) und die Zustellung per Ricevuta di Consegna für jede gesendete Rechnung zu bestätigen.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Richten Sie eine 10-jährige conservazione-sostitutiva-Archivierung ein', 'Dies ist ein eigenständiges digitales Aufbewahrungsregime nach italienischem Recht — stellen Sie sicher, dass Ihre Archivierungslösung dessen spezifische Integritäts- und Zugänglichkeitsanforderungen erfüllt, nicht nur allgemeine Dateispeicherung.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Implementieren Sie die TD17–TD19-Meldung bei grenzüberschreitendem Handel', 'Bauen Sie das 12-Tage-Meldefenster in Ihren Prozess für Dienstleistungen aus dem Ausland und Waren aus EU-/Nicht-EU-Quellen ein.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 6;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Enregistrez un Codice Destinatario, ou prévoyez d''utiliser la PEC', 'Les entreprises italiennes peuvent s''enregistrer directement auprès de l''Agenzia delle Entrate via le portail Fatture e Corrispettivi. Les entreprises non italiennes passent généralement par un intermédiaire ou le module SDI de leur ERP.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Adaptez vos données à FatturaPA v1.9.1', 'Validez spécifiquement par rapport au schéma actuel — la bascule du 15 mai 2026 signifie que tout ce qui vise encore une version antérieure sera purement et simplement rejeté.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Apposez une signature électronique qualifiée sur chaque facture', 'Utilisez le format XAdES ou CAdES (.p7m) — il s''agit d''une exigence au niveau du document qui s''applique avant la transmission, et non quelque chose que le SDI ajoute en votre nom.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez votre canal de transmission', 'Choisissez parmi PEC, téléversement web, SFTP ou services web SDICoop selon votre volume et votre infrastructure existante — SDICoop convient le mieux aux intégrations automatisées à volume élevé.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place la gestion des rejets et le suivi des accusés', 'Configurez des flux de travail pour détecter rapidement les rejets Notifica di Scarto (vérifiez d''abord la validité du Codice Fiscale/Partita IVA) et confirmer la livraison via Ricevuta di Consegna pour chaque facture envoyée.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en place un archivage conservazione sostitutiva de 10 ans', 'Il s''agit d''un régime de conservation numérique distinct en vertu du droit italien — vérifiez que votre solution d''archivage répond à ses exigences spécifiques d''intégrité et d''accessibilité, pas seulement à un stockage de fichiers classique.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Mettez en œuvre la déclaration TD17–TD19 si vous commercez à l''international', 'Intégrez le délai de déclaration de 12 jours dans votre processus pour les services de l''étranger et les biens provenant de l''UE/hors UE.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Italy' AND ds.sort_order = 6;

