INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'de', 'Nur formal — korrekte Mehrwertsteuer, verspätete Einreichung', 'Fester Betrag von 250 €/Rechnung, bis zu 2.000 €/Quartal', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Italy' AND pr.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Substantielle — TVA incorrecte/non déclarée', '90 %–180 % du montant de TVA non déclaré par facture', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Italy' AND pr.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT pr.id, 'fr', 'Purement formelle — TVA correcte, dépôt tardif', '250 € fixes par facture, jusqu''à 2 000 €/trimestre', NULL FROM deep_dive_penalty_rows pr JOIN countries co ON co.id = pr.country_id WHERE co.name_en = 'Italy' AND pr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🕊️ La divulgación voluntaria reduce las sanciones', NULL, NULL, 'El ravvedimento operoso permite a las empresas reducir las sanciones corrigiendo voluntariamente los errores antes de que la autoridad fiscal abra una auditoría — conviene usarlo de forma proactiva en lugar de esperar a ser detectado.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🔍 Códigos de rechazo comunes de v1.9.1', NULL, NULL, 'El error 00305 (Codice Destinatario inválido/desconocido), el 00400 (subcódigo Natura obsoleto) y el 00404 (código de método de pago obsoleto) representan una parte importante de los rechazos reales desde la actualización del esquema.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🏛️ Tratamiento especial de San Marino', NULL, NULL, 'La facturación transfronteriza con San Marino se realiza a través de un canal HUB-SM dedicado — una excepción reducida pero persistente al flujo doméstico estándar del SDI.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🕊️ Freiwillige Offenlegung reduziert Sanktionen', NULL, NULL, 'Der Ravvedimento operoso ermöglicht es Unternehmen, Bußgelder durch freiwillige Korrektur von Fehlern zu reduzieren, bevor die Steuerbehörde eine Prüfung einleitet — es lohnt sich, dies proaktiv zu nutzen, statt auf eine Entdeckung zu warten.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🔍 Häufige v1.9.1-Ablehnungscodes', NULL, NULL, 'Fehler 00305 (ungültiger/unbekannter Codice Destinatario), 00400 (veralteter Natura-Subcode) und 00404 (veralteter Zahlungsmethodencode) machen seit dem Schema-Update einen großen Teil der tatsächlichen Ablehnungen aus.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🏛️ Sonderbehandlung für San Marino', NULL, NULL, 'Die grenzüberschreitende Rechnungsstellung mit San Marino läuft über einen eigenen HUB-SM-Kanal — eine schmale, aber dauerhafte Ausnahme vom regulären inländischen SDI-Ablauf.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🕊️ La divulgation volontaire réduit les sanctions', NULL, NULL, 'Le ravvedimento operoso permet aux entreprises de réduire les sanctions en corrigeant volontairement les erreurs avant que l''administration fiscale n''ouvre un contrôle — mieux vaut l''utiliser de manière proactive plutôt que d''attendre d''être repéré.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🔍 Codes de rejet courants de la v1.9.1', NULL, NULL, 'L''erreur 00305 (Codice Destinatario invalide/inconnu), 00400 (sous-code Natura obsolète) et 00404 (code de mode de paiement obsolète) représentent une grande part des rejets réels depuis la mise à jour du schéma.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🏛️ Traitement particulier de Saint-Marin', NULL, NULL, 'La facturation transfrontalière avec Saint-Marin passe par un canal HUB-SM dédié — une exception étroite mais persistante au flux SDI domestique standard.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Italy' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

